fn broadcast_arrays(a: Vec<i8>, b: Vec<i8>) -> (Vec<i8>, Vec<i8>) {
    let m = a.len();
    let n = b.len();
    let max_len = m.max(n);

    // Helper to broadcast a vec to length max_len:
    // - If length == 1, repeat the single element max_len times.
    // - If length == max_len, clone as is.
    // According to problem, inputs are guaranteed compatible, so these are only possibilities.
    fn broadcast(input: &Vec<i8>, max_len: usize) -> Vec<i8> {
        match input.len() {
            1 => vec![input[0]; max_len],
            len if len == max_len => input.clone(),
            _ => unreachable!("Inputs are guaranteed to be compatible"),
        }
    }

    // Build output arrays using broadcasting rules:
    // If both same length, outputs are just clones of inputs.
    // If one length 1 others longer, broadcast length-1 vec, clone the longer vec.

    let out_a = broadcast(&a, max_len);
    let out_b = broadcast(&b, max_len);

    (out_a, out_b)
}